def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive_ids = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_ids.append(oid)

    # If no one alive, take what we can
    if not alive_ids:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace (immediate reaction)
    yesterday_bids = []
    for oid in alive_ids:
        prev = opponents_status[oid].get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Supply pressure: if supply is near/under our requirement, competition likely increases
    # (supply is float; convert to an integer bucket for stable decisions)
    supply_bucket = int(round(supply))
    tight_supply = supply_bucket <= WATER_REQ

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    # Base aggressiveness
    # If Bob-like pressure exists (high previous bid), we bid enough to beat typical mid bidders.
    # Otherwise, bid around midrange to conserve budget.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Strong competition yesterday
        if hp > 3:
            bid_target = DAILY_SALARY * 0.30
        else:
            bid_target = DAILY_SALARY * 0.90
    else:
        # Moderate competition
        if tight_supply:
            bid_target = DAILY_SALARY * 0.65
        else:
            bid_target = DAILY_SALARY * 0.50

    # If tight supply, slightly raise; if my hp is low, raise more
    if tight_supply:
        bid_target *= 1.15
    if hp <= 2:
        bid_target *= 1.30
    elif hp <= 4:
        bid_target *= 1.10

    # Try to stay below or near what would likely secure water against typical bids
    # Use highest_prev_bid as a ceiling reference, but don't overpay.
    # Ensure we don't exceed budget.
    # If competition was high, attempt a small overbid.
    if highest_prev_bid > 0:
        # Only overbid if we can afford it comfortably
        overbid_target = min(budget, highest_prev_bid + 3.0)
        # Blend: prefer our computed target unless overbid is much cheaper
        bid = min(overbid_target, bid_target)
    else:
        bid = bid_target

    # Final clamp
    if budget <= 0:
        return 0.0
    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    # Avoid bidding too low when supply is tight and we need water
    if tight_supply and my_status.get('no_water_days', 0) >= 1:
        floor_bid = min(budget, DAILY_SALARY * 0.55)
        if bid < floor_bid:
            bid = floor_bid

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    strong_prev = []
    weak_or_dead = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 50:
                    strong_prev.append(float(bid))
        else:
            weak_or_dead += 1

    if not alive_opps:
        return max(0.0, min(float(budget), 18.0))

    contested_units = supply / float(WATER_REQ)
    tight_supply = contested_units < (len(alive_opps) + 1)
    very_tight = contested_units < len(alive_opps)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days == 1:
        urgency += 1

    if very_tight:
        urgency += 2
    elif tight_supply:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency >= 6:
        target = max(76.0, highest_prev + 4.0)
    elif urgency >= 4:
        target = max(64.0, highest_prev + 2.0)
    elif urgency >= 2:
        if tight_supply:
            target = max(56.0, highest_prev + 1.0)
        else:
            target = max(42.0, avg_prev)
    else:
        if not tight_supply:
            target = 28.0
        else:
            target = max(46.0, avg_prev - 2.0)

    active_strong = 0
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None and float(bid) >= 55.0:
            active_strong += 1

    if active_strong >= 2 and tight_supply and urgency < 4:
        target -= 6.0

    if supply >= 22 and urgency < 4:
        target -= 8.0
    elif supply <= 17:
        target += 4.0

    reserve_floor = 0.0
    if day <= 6:
        reserve_floor = 25.0
    elif day <= 8:
        reserve_floor = 10.0

    spend_cap = max(0.0, float(budget) - reserve_floor)
    if urgency >= 5:
        spend_cap = float(budget)

    bid = min(target, spend_cap, float(budget))

    if budget <= 0:
        return 0.0

    min_defensive = 0.0
    if hp <= 2 or no_water_days >= 2:
        min_defensive = 72.0
    elif hp <= 4 or no_water_days == 1:
        min_defensive = 58.0

    if min_defensive > 0:
        bid = max(bid, min(min_defensive, float(budget)))

    if bid < 0:
        bid = 0.0

    return float(round(min(bid, float(budget)), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    bud = my_status['budget']
    hp = my_status['hp']
    no_water = my_status['no_water_days']

    alive_opps = {k: v for k, v in opponents_status.items() if v['alive']}

    # Extract last bids from traces
    bob_last_bid = None
    david_last_bid = None
    for opp_id, opp in alive_opps.items():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev:
            bid = prev['bid']
            if opp_id == 'Bob':
                bob_last_bid = bid
            elif opp_id == 'David':
                david_last_bid = bid

    # Base bid: if no water for 2+ days, bid high
    if no_water >= 2:
        return min(bud, DAILY_SALARY * 0.95)

    # Determine needed water
    water_needed = max(0, WATER_REQ - supply)
    if water_needed <= 0:
        # No bidding needed, bid minimal to not waste money
        return min(bud, max(0.0, DAILY_SALARY * 0.1))

    # Strategic bidding based on opponents
    if bob_last_bid is not None and bob_last_bid > DAILY_SALARY * 0.75:
        # Bob is aggressive; only outbid if desperate
        if hp <= 3:
            # Need water, try to beat Bob by small margin
            target = bob_last_bid + 1.5
            return min(bud, target)
        else:
            # Let Bob win, bid low to save budget
            return min(bud, DAILY_SALARY * 0.4)
    if david_last_bid is not None:
        # David moderate; outbid him slightly
        target = david_last_bid + 1.5
        return min(bud, max(target, DAILY_SALARY * 0.5))

    # Default: conservative
    if hp <= 2:
        return min(bud, DAILY_SALARY * 0.7)
    return min(bud, DAILY_SALARY * 0.45)

